"""Verify a full judge ledger with original files generated by this offline test."""

from base64 import b64encode
from collections import Counter
from hashlib import sha256
import json
from pathlib import Path
from uuid import uuid4

import pytest

from tests.acceptance.judge_test_material import judge_test_material
from tests.acceptance.test_judge_qualification import candidate, samples
from tests.support.agent_acceptance import (
    AcceptancePlan,
    CaseContext,
    CaseOutcome,
    CaseRegistry,
    FrozenParentBudget,
    LiveAuthorization,
    LiveGate,
    RunResult,
    SharedControlError,
    export_review,
    prepare_live,
    review_report,
)
from tests.support.agent_acceptance.judge_qualification import (
    freeze_judge_study,
    judge_executions,
    qualification_report,
    register_judge_study,
)
from tests.support.agent_acceptance.reporting import assess, publish_evidence, version_facts


REQUEST_COUNT = 130
REQUEST_MICROUSD = 122_880
PARENT_MICROUSD = 15_974_400
FIXTURE_ORIGIN = "generated_offline_judge_ledger_test"


def record_synthetic_judge_call(context: CaseContext, label: str, material: str) -> CaseOutcome:
    """Drive the real ledger with a generated request and response fixture."""
    assert context.live_gate is not None and context.execution is not None
    gate = context.live_gate
    execution = context.execution
    call_id = f"synthetic-call:{execution.execution_id}"
    identity = {"actor": "judge", "purpose": execution.judge_purpose, "judge_call_id": call_id,
                "delegation_id": None, "number": None}
    request = json.dumps({"contents": [{"role": "user", "parts": [{"text": material}]}]}, ensure_ascii=False)
    answer = json.dumps({"conclusions": {"sufficiency": label},
                         "reasons": {"sufficiency": "Response generated by the offline ledger test."}})
    response = json.dumps({
        "candidates": [{"finishReason": "STOP", "content": {"parts": [{"text": answer}]}}],
        "usageMetadata": {"promptTokenCount": 40, "candidatesTokenCount": 6, "thoughtsTokenCount": 2},
    })
    number = gate.reserve(
        case_id=context.case_id, protocol=context.protocol, actor="judge", purpose=execution.judge_purpose,
        role="judge", sdk_input_id=call_id, judge_call_id=call_id,
        request_sha256=sha256(request.encode("utf-8")).hexdigest(),
    )
    assert number == execution.order
    assert gate.accounting_report()["attempts"][-1]["state"] == "reserved"
    gate.mark_http_started(number)
    assert gate.accounting_report()["attempts"][-1]["state"] == "http_started"
    exchange = {
        "ledger_number": number, "sdk_input_id": call_id, "request_identity": identity,
        "request_utf8": request, "received_utf8": response, "status": 200,
        "transport_provenance": "fixed_fixture", "fixture_origin": FIXTURE_ORIGIN,
        "received_base64": b64encode(response.encode("utf-8")).decode("ascii"),
        "response_metadata": {"byte_layer": "transport", "source": "fixed_fixture",
                              "content_encoding": None, "content_type": "application/json"},
    }
    gate.mark_response_complete(number, exchange)
    original = context.root / "synthetic-judge-exchange.json"
    original.write_text(json.dumps({
        "run_id": context.run_id, "case_id": context.case_id, "protocol": context.protocol,
        "execution_id": execution.execution_id, "fixture_origin": FIXTURE_ORIGIN, "product_attempts": [],
        "sdk_inputs": [{"sdk_input_id": call_id, "request_identity": identity}], "exchanges": [exchange],
    }, ensure_ascii=False), encoding="utf-8")
    return CaseOutcome("passed", {"fixture_origin": FIXTURE_ORIGIN}, {"exchange": original},
                       case_id=context.case_id, protocol=context.protocol, execution_id=execution.execution_id,
                       execution_status="passed")


def assert_qualification_score(report, *, agreements: int, unknown: int, status: str) -> None:
    assert report["fixture_status"] == status
    assert report["actual_qualification"] == "not-started"
    assert report["calibration"]["planned_calls"] == 30
    assert report["calibration"]["completed_rounds"] == 1
    score = report["qualification"]
    assert (score["planned"], score["agreements"], score["unknown"]) == (100, agreements, unknown)
    assert score["human_positive_denominator"] == score["human_negative_denominator"] == 50


def test_full_synthetic_judge_ledger_preserves_frozen_scores_and_reopen(prepared_root, acceptance_public_root, request):
    source = Path(__file__).resolve().parents[2]
    with judge_test_material(source) as root:
        calibration = samples(root / "calibration", "cal", 6)
        qualification = samples(root / "qualification", "qual", 20)
        study = freeze_judge_study(root / "study", calibration=calibration, qualification=qualification,
                                   candidate=candidate(root), mode="synthetic_test")
        rows = judge_executions(study)
        expected = [f"judge:{purpose}:1:{sample.output_id}" for purpose, group in (
            ("calibration", calibration), ("qualification", qualification),
        ) for sample in group]
        assert len(expected) == REQUEST_COUNT
        assert [row.execution_id for row in rows] == expected
        assert all(row.dependencies == () for row in rows[:30])
        assert all(row.dependencies == tuple(expected[:30]) for row in rows[30:])

        registry = CaseRegistry()
        register_judge_study(registry, study, fixed_replies={})
        parent = FrozenParentBudget(
            parent_id=f"synthetic-judge-ledger-{prepared_root.name}", accounting_root=prepared_root,
            request_cap=REQUEST_COUNT, phase_microusd={"screening": 0, "quality": 0, "judge": PARENT_MICROUSD},
            reserve_microusd=0, profile="synthetic",
        )
        plan = AcceptancePlan(executions=rows, parent_budget=parent)
        bundle = prepare_live(plan.model_copy(update={"mode": "prepare-live"}), root=prepared_root, registry=registry)
        grant = LiveAuthorization(
            authorization_id="synthetic-judge-ledger", binding=bundle.binding, transport="mock",
            total_limit=REQUEST_COUNT, total_microusd=PARENT_MICROUSD, parent_budget_id=parent.parent_id,
            case_limits=dict.fromkeys(expected, 1), case_microusd=dict.fromkeys(expected, REQUEST_MICROUSD),
        )
        gate = LiveGate(prepared_root, registry, grant)
        parent_index = gate.parent_binding_path(parent.parent_id)
        assert not parent_index.exists()
        request.addfinalizer(lambda: parent_index.unlink(missing_ok=True))

        result = RunResult(uuid4().hex, [], acceptance_public_root / "result.json", version_facts(plan, registry),
                           registry.catalogue(), rows)
        with gate.owner():
            gate.validate_plan(plan)
            for row, sample in zip(rows, [*calibration, *qualification], strict=True):
                case = registry.cases[row.case_id]
                case_root = acceptance_public_root / row.case_id / row.protocol / row.directory_name
                case_root.mkdir(parents=True)
                execution_gate = gate.for_execution(row.execution_id)
                context = CaseContext(case_root, row.protocol, result.run_id, row.case_id,
                                      live_gate=execution_gate, execution=row)
                assert sample.fixture_reference is not None
                label = sample.fixture_reference.conclusions["sufficiency"]
                material = (source / row.material_path).read_text(encoding="utf-8")
                outcome = record_synthetic_judge_call(context, label, material)
                publish_evidence(context, outcome, case)
                assess(case, outcome)
                outcome.facts["budget"].pop("attempts")
                execution_gate.finish_execution(outcome)
                result.cases.append(outcome)
        result.save("offline")

        accounting = gate.accounting_report()
        assert accounting["parent_budget_id"] == parent.parent_id
        assert json.loads(parent_index.read_bytes())["accounting_root"] == str(prepared_root.resolve())
        assert accounting["binding"] == bundle.binding
        assert accounting["phase_microusd"] == {"screening": 0, "quality": 0, "judge": PARENT_MICROUSD}
        assert accounting["cost_limit_microusd"] == accounting["occupied_microusd"] == PARENT_MICROUSD
        assert accounting["reserve_microusd"] == accounting["not_sent"] == 0
        assert accounting["request_limit"] == accounting["reserved_requests"] == accounting["actual_http"] == REQUEST_COUNT
        assert accounting["completed_responses"] == accounting["usage_estimates"] == REQUEST_COUNT
        assert accounting["completed_executions"] == expected
        assert accounting["role_usage"] == {"judge": REQUEST_COUNT}
        assert not accounting["stopped"] and not accounting["case_stops"]
        attempts = accounting["attempts"]
        assert [item["execution_id"] for item in attempts] == expected
        assert Counter(item["purpose"] for item in attempts) == {"calibration": 30, "qualification": 100}
        for row, item, outcome in zip(rows, attempts, result.cases, strict=True):
            assert (item["number"], item["case_id"], item["protocol"]) == (row.order, row.case_id, "google")
            assert (item["stage"], item["role"], item["actor"], item["purpose"], item["state"]) == (
                "judge", "judge", "judge", row.judge_purpose, "response_complete",
            )
            assert item["authorization_id"] == grant.authorization_id
            assert item["reservation_microusd"] == item["occupied_microusd"] == REQUEST_MICROUSD
            assert item["usage_estimate_microusd"] == 130 and item["supplier_final_microusd"] is None
            assert item["sdk_input_id"] == item["judge_call_id"] == f"synthetic-call:{row.execution_id}"
            assert item["product_number"] is None
            assert outcome.facts["fixture_origin"] == FIXTURE_ORIGIN
            assert outcome.facts["real_http_attempts"] == 0

        report = qualification_report(study, result_path=result.result_path)
        assert_qualification_score(report, agreements=100, unknown=0, status="qualified")
        assert [item["execution_id"] for item in report["judge_call_results"]] == expected
        assert all(item["issue"] is None for item in report["judge_call_results"])
        package = export_review(result.result_path, acceptance_public_root / "judge-review")
        review = review_report(package)
        assert review["outputs"] == review["case_results"] == []
        assert [item["execution_id"] for item in review["judge_call_results"]] == expected
        assert all(item["call_status"] == "passed" and item["qualification"] == "not_measured"
                   for item in review["judge_call_results"])

        reopened = LiveGate(prepared_root, registry, grant)
        reopened.validate_plan(plan)
        reopened_cases = [reopened.for_execution(identity).recorded_outcome() for identity in expected]
        assert reopened_cases == result.cases
        previous = reopened.for_execution(expected[-1])
        with pytest.raises(SharedControlError, match="result cannot be replaced"):
            previous.finish_execution(reopened_cases[-1])
        repeat_root = acceptance_public_root / "reopen"
        repeat_root.mkdir()
        repeat = RunResult(uuid4().hex, reopened_cases, repeat_root / "result.json", planned_executions=rows)
        repeat.save("offline")
        assert_qualification_score(qualification_report(study, result_path=repeat.result_path),
                                   agreements=100, unknown=0, status="qualified")
        assert reopened.accounting_report() == accounting

        final_evidence = result.cases[-1].evidence
        original = final_evidence["exchange"]
        index = final_evidence["evidence_index"]
        body = original.read_bytes()
        index_body = index.read_bytes()
        try:
            original.unlink()
            missing = qualification_report(study, result_path=result.result_path)
            original.write_bytes(body + b"\n")
            corrupt = qualification_report(study, result_path=result.result_path)
            changed_exchange = json.loads(body)
            changed_exchange["sdk_inputs"][0]["request_identity"]["actor"] = "main"
            changed_body = json.dumps(changed_exchange, ensure_ascii=False).encode("utf-8")
            original.write_bytes(changed_body)
            changed_index = json.loads(index_body)
            changed_index["links"]["exchange"]["sha256"] = sha256(changed_body).hexdigest()
            index.write_text(json.dumps(changed_index), encoding="utf-8")
            wrong_identity = qualification_report(study, result_path=result.result_path)
        finally:
            original.write_bytes(body)
            index.write_bytes(index_body)
        for damaged in (missing, corrupt, wrong_identity):
            assert_qualification_score(damaged, agreements=99, unknown=1, status="incomplete")
            assert damaged["judge_call_results"][-1]["execution_id"] == expected[-1]
            assert damaged["judge_call_results"][-1]["conclusions"] is None
        assert corrupt["judge_call_results"][-1]["issue"] == "native_original_fingerprint_changed"
        assert wrong_identity["judge_call_results"][-1]["issue"] == "sdk_identity_or_complete_input_changed"
        assert reopened.accounting_report() == accounting
